from pathlib import Path
import shutil,json,html
P=Path(__file__).resolve().parents[1];R=P.parents[1]
for d in ['assets/fonts','assets/images','tokens','review']:(P/d).mkdir(parents=True,exist_ok=True)
for p in (R/'design-system/assets/fonts').glob('*'):shutil.copy2(p,P/'assets/fonts'/p.name)
for n in ['fonts','colors','typography','spacing','effects']:shutil.copy2(R/f'design-system/tokens/{n}.css',P/f'tokens/{n}.css')
shutil.copy2(R/'brand/red-white-and-clix-logo.png',P/'assets/images/logo.png')
shutil.copy2(R/'design-system/assets/photography/fb-a773fb13f49d.jpg',P/'assets/images/community-tables.jpg')
shutil.copy2(R/'design-system/assets/photography/fb-b1e412d378a4.jpg',P/'assets/images/tabletop-match.jpg')
manifest=json.loads((R/'design-system/assets/photography/MANIFEST.json').read_text())
selected=[x for x in manifest['assets'] if x['file'] in ['fb-a773fb13f49d.jpg','fb-b1e412d378a4.jpg']]
(P/'assets/images/provenance.json').write_text(json.dumps({'note':manifest['notes'],'selected':selected},indent=2))
def a(text,url,secondary=False):return f'<a class="button {"secondary" if secondary else ""}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def header(active):
 links=[('index.html','Home'),('events.html','Events'),('about.html','Our story'),('donate.html','Give')]
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==active else '')+f'>{label}</a>' for url,label in links)
 return f'''<a class="skip" href="#main">Skip to content</a><div class="review-bar"><span>DESIGN PREVIEW</span><p>Working event details • checkout is not connected</p><a href="review.html">Review notes</a></div><header class="site-header wrap"><a class="brand" href="index.html" aria-label="Red White and Clix home"><img src="assets/images/logo.png" width="120" height="120" alt=""><span>RED WHITE<br>AND CLIX<small>One Community. One Mission.</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-menu"><summary>Menu <span aria-hidden="true">＋</span></summary><nav aria-label="Mobile navigation">{nav}</nav></details></header>'''
def footer():return '''<footer class="site-footer"><div class="wrap footer-grid"><div><h2>One Community.<br>One Mission.</h2><p>Veteran-founded tabletop events.<br>Lafayette, Indiana · The Midwest.</p></div><div><h3>Find your next step</h3><a href="events.html">Explore the event</a><a href="about.html">Our story</a><a href="https://www.redwhiteandclix.org/veteran-resources">Veteran resources ↗</a><a href="https://www.redwhiteandclix.org/shop">Visit the current shop ↗</a></div><div><h3>Let’s talk</h3><a href="mailto:redwhiteandclix@gmail.com">redwhiteandclix@gmail.com</a><a href="tel:+15742659585">574-265-9585</a><p>Questions about playing,<br>sponsoring or volunteering?<br>Get in touch.</p></div></div><div class="wrap footer-bottom"><span>Red White and Clix</span><span>Local design preview · September 2026</span><a href="review.html">Review status</a></div></footer>'''
def render(name,title,desc,body):
 (P/name).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{html.escape(desc,quote=True)}"><title>{html.escape(title)} | Red White and Clix preview</title><link rel="stylesheet" href="site.css"><link rel="icon" href="data:,"></head><body>{header(name)}<main id="main">{body}</main>{footer()}</body></html>')
def cta():return '<section class="cta-band"><div class="wrap"><div><p class="eyebrow inverse">YOUR NEXT SEAT</p><h2>Come for the game.<br>Find your community.</h2></div>'+a('Explore the event','events.html')+'</div></section>'
